rep = CheckReport("calc_of_TxT_hatZxhatY: 直積作用の 2x2 行列表示")
for M in [_sage_const_2 ,_sage_const_3 ,_sage_const_4 ]:
    rng_mu = list(range(-M,_sage_const_0 )) + list(range(_sage_const_1 ,M+_sage_const_1 ))
