            g1 = principal_sqrt_of_V1pm(K1, M, '-')
            g2 = V2_op(K2, M)
            # 列ごとに (hatZ, hatY) B の各成分と突き合わせる
            rep.close(T_conj(g1, Zm), B1[_sage_const_0 ,_sage_const_0 ]*Zm + B1[_sage_const_1 ,_sage_const_0 ]*Ym, f"M={M} mu={mu}: B_1 の第1列")
